import{_ as a,o as t,c as n,a0 as s}from"./chunks/framework.BYCjvD8D.js";const u=JSON.parse('{"title":"Algorithm and mathematics","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm.md","filePath":"algorithm.md"}'),i={name:"algorithm.md"};function o(r,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="algorithm-and-mathematics" tabindex="-1">Algorithm and mathematics <a class="header-anchor" href="#algorithm-and-mathematics" aria-label="Permalink to &quot;Algorithm and mathematics&quot;">​</a></h1><h2 id="state-→-policy-→-action" tabindex="-1">State → policy → action <a class="header-anchor" href="#state-→-policy-→-action" aria-label="Permalink to &quot;State → policy → action&quot;">​</a></h2><p>Every frame, a small observation vector describes local terrain and danger. There are <strong>169 sensory inputs</strong>, arranged in a 13 × 13 grid. One extra bias neuron is also available. Three output neurons select <strong>left</strong>, <strong>right</strong>, and <strong>jump</strong>.</p><p>A neural policy maps an observation vector to button presses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Local terrain/enemy occupancy</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>Neural weights and topology</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>Left / right / jump</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>Deterministic game step</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>New observations, progress and hazards</span></span></code></pre></div><h2 id="genome" tabindex="-1">Genome <a class="header-anchor" href="#genome" aria-label="Permalink to &quot;Genome&quot;">​</a></h2><p>A genome stores nodes and enabled/disabled connections. Each connection stores its source, destination, weight and global <strong>innovation number</strong>. Innovation markers allow genes inherited by separate lineages to be aligned during crossover.</p><h2 id="structural-mutation" tabindex="-1">Structural mutation <a class="header-anchor" href="#structural-mutation" aria-label="Permalink to &quot;Structural mutation&quot;">​</a></h2><ul><li><strong>Weight mutation:</strong> perturb or replace a connection weight.</li><li><strong>Add connection:</strong> connect compatible, previously unconnected nodes while preserving feed-forward ordering.</li><li><strong>Split connection:</strong> disable a connection and insert a hidden node plus two replacement connections.</li><li><strong>Enable/disable:</strong> occasionally toggle a connection gene.</li></ul><h2 id="species" tabindex="-1">Species <a class="header-anchor" href="#species" aria-label="Permalink to &quot;Species&quot;">​</a></h2><p>Genomes are clustered by structural/weight compatibility. Each species has a fitness share so novel structures are less likely to be eliminated immediately by established high-performing structures.</p><h2 id="fitness" tabindex="-1">Fitness <a class="header-anchor" href="#fitness" aria-label="Permalink to &quot;Fitness&quot;">​</a></h2><p>The current illustrative objective is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fitness = max(0, maximum horizontal progress − starting position)</span></span>
<span class="line"><span>        + 150 if the goal was reached</span></span></code></pre></div><p>This objective is <em>not</em> asserted to reproduce the original Lua program. It can encourage reward hacking and overfitting; we will evaluate alternative reward/fitness definitions in future milestones.</p><h2 id="what-it-is-and-isn-t" tabindex="-1">What it is and isn&#39;t <a class="header-anchor" href="#what-it-is-and-isn-t" aria-label="Permalink to &quot;What it is and isn&#39;t&quot;">​</a></h2><p>This v0.1 is <strong>NEAT-inspired and implemented</strong>, not a proof of canonical NEAT equivalence. It uses deterministic simulation, shared innovation tracking, species-based competition, crossover, elitism and structural mutation. It does not yet implement all original paper heuristics (such as sophisticated species staleness controls, adaptive distance thresholds or exhaustive population diversity experiments).</p><p>Neuroevolution optimises episodic performance by evolving populations. It is related to reinforcement learning by its control problem and reward/fitness feedback, but it is not gradient-based deep reinforcement learning.</p><h2 id="later-experiments" tabindex="-1">Later experiments <a class="header-anchor" href="#later-experiments" aria-label="Permalink to &quot;Later experiments&quot;">​</a></h2><ul><li>Full canonical NEAT baseline including species stagnation and carefully reported mutation parameters.</li><li>More challenging levels, randomized seeds and unseen-test scenarios.</li><li>Pixel versus structured observations; convolutional neural networks.</li><li>Deep Q-Networks, policy-gradient algorithms and modern actor–critic baselines.</li><li>Python Gymnasium / Stable-Baselines3 bridge, <strong>later</strong>, not needed for the browser experiment.</li><li>WebGPU compute acceleration for batch-friendly operators if profiling supports it.</li></ul>`,20)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
